import{_ as s,o as e,c as r,a2 as d}from"./chunks/framework.BXzK3EA4.js";const o="/assets/d73e246a4518de69.CMCTnLVU.png",p="/assets/5f5f7ca5a1ffe4b5.HEkD0yyU.png",a="/assets/1e8846a1cefba9f9.MguWAsMP.png",n="/assets/df3aeaf70063aa42.5QLEmXnr.png",i="/assets/b7338c4bb2e38c39.CrWZDOEu.png",c="/assets/d18be98d194049ad.cXTWB26U.png",C=JSON.parse('{"title":"云原生安全组设置","description":"","frontmatter":{"title":"云原生安全组设置"},"headers":[],"relativePath":"ops-knowledge-base/cloud-native/security-group-setup.md","filePath":"ops-knowledge-base/cloud-native/security-group-setup.md","lastUpdated":1788259091000}'),P={name:"ops-knowledge-base/cloud-native/security-group-setup.md"};function l(_,t,g,u,m,I){return e(),r("div",null,[...t[0]||(t[0]=[d('<p>添加安全组规则</p><p>创建安全组后，您需要添加安全组规则才能使安全组发挥作用。您可以通过添加安全组规则，允许或禁止安全组内的云服务器实例对公网或私网的访问。</p><p>同类型规则间依赖优先级决定最终执行的规则。当云服务器加入了多个安全组时，多个安全组会从高到低依次匹配规则。最终生效的安全组规则如下。</p><ul><li>如果两条安全组规则只有授权策略不同：目前是随机生效。</li><li>如果两条安全组规则只有优先级不同：优先级高的规则生效。</li></ul><ol><li>在没有添加安全组前，需要在购买服务里 – 云原生 – 点击安全组进行添加</li></ol><p>2.设置安全组的名称，点击提交后，在产品服务里 – 云原生 – 点击安全组就可以看到</p><p><img src="'+o+'" alt=""></p><p>3.点击进入即可设置安全组规则</p><p><img src="'+p+'" alt=""></p><p><img src="'+a+'" alt=""></p><p><img src="'+n+'" alt=""></p><p>4.输入安全组规则的相关信息，如优先级，协议类型，规则方向等，如下表所示。</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>名称</strong></td><td><strong>描述</strong></td></tr><tr><td>名称</td><td>安全组规则的名称</td></tr><tr><td>优先级</td><td>优先级数值越小，优先级越高，取值范围为 0~100</td></tr><tr><td>方向</td><td><strong>上行规则</strong>： 指的是从云资源访问外部。上行规则和端口默认放行。为保证安全，对于 Windows 云服务器系统判定了一些高危端口，默认将其加入了安全组并禁止。对于 Windows 云服务器，系统默认限制了以下上行端口。 - 协议 TCP：端口 3389/1433/445/135/139 - 协议 UDP：端口 1434/445/135/137/138 - Windows 云服务器向外发起远程桌面连接，您需要在安全组中放行规则 tcp 上行 3389 端口。 Windows 云服务器向外发起 SQL Server 连接，您需要在安全组中放行规则 tcp 上行 1433 端口 <strong>下行规则</strong>： 指从外部访问云资源。未配置的下行规则和端口默认拒绝访问。 TCP 端口 445/5554/9996 是病毒震荡波所使用的端口，可能会被 IDC 屏蔽，为保证资源正常访问，建议使用其他端口。</td></tr><tr><td>行为</td><td><strong>允许</strong>：放行该端口相应的访问请求 <strong>拒绝</strong>：直接丢弃数据包，不会返回任何回应信息。 说明 如果两个安全组规则其他都相同只有行为不同，则拒绝生效，允许不生效。</td></tr><tr><td>协议</td><td>协议类型包括： - ALL：支持全部协议类型。 - TCP：支持 TCP 协议。 - UDP：支持 UDP 协议。 - ICMP：支持 ICMP 协议。 - GRE：支持 GRE 协议。 - ESP：支持 ESP 协议。 - AH：支持 AH 协议。 - IPIP：支持 IPIP 协议。 - VRRP：支持 VRRP 协议。 *IPV6：支持 ICP6 协议。 - IPV6-ICMP：仅支持 ICMP（IPV6） 协议。 - IPENCAP：支持 IPENCAP 协议。</td></tr><tr><td>端口范围</td><td>协议类型为自定义TCP或自定义UDP时，可手动设置起始端口和结束端口访问。</td></tr><tr><td>IP</td><td>在下行规则中需要填写源 IP，在上行规则中需要填写目标IP，例如 192.168.9.1/24 或 fe80::5054:a8ff:fe81:a71e/64 等，不填表示所有IP地址。</td></tr></tbody></table><p><img src="'+i+'" alt=""></p><p>5.设置完后，关联需要的云服务器即可</p><p><img src="'+c+'" alt=""></p>',16)])])}const b=s(P,[["render",l]]);export{C as __pageData,b as default};
